    Object.assign(T.en,{meal:'Change of pace',onePot:'Change of pace',boiledMeat1:'Put the meat in cool water with ginger and a little salt. Bring it gently to a boil and skim.',boiledMeat2:'Lower the heat and cook until done; a whole chicken takes longer, so check the thigh.',boiledMeat3:'Rest briefly, then slice. Serve with fresh greens or dipping sauce.',steam1:'Season the fish with ginger, pepper, and a little fish sauce. Place on a heatproof plate.',steam2:'Bring the steamer to a boil and steam until the fish turns opaque and flakes easily.',steam3:'Add scallions and a little hot soy sauce, then serve immediately.',eggDish1:'Beat the eggs with a little fish sauce. If using minced pork, cook it first.',eggDish2:'Add the eggs to a pan or steamer. Cook over medium heat until softly set.',eggDish3:'Finish with scallions and make sure the eggs are fully cooked.',fry1:'Pat the ingredients dry to reduce splatter. Heat a thin layer of oil in a pan.',fry2:'Fry or pan-sear each side until golden and cooked through.',fry3:'Drain briefly. For a fish-sauce glaze, add the sauce at the end and toss quickly.',menuItemCount:'98 home-style dishes',mealPrep:'Prep ingredients',mealCook:'Cook in one pot',mealFinish:'Taste, then serve hot for everyone.',mealRice1:'Use chilled rice so the grains stay separate. Prep the chicken and vegetables, then beat the eggs.',mealRice2:'Sauté garlic and shallot, cook the chicken through, then add vegetables and stir until just tender.',mealRice3:'Add the rice and stir-fry until fluffy. Push it aside to scramble the egg, then mix and season.',mealSoup1:'Wash the ingredients. Simmer chicken or meat for broth, skimming to keep it clear.',mealSoup2:'Cook the noodles according to the package directions and drain.',mealSoup3:'Add vegetables and protein to the broth; cook until tender and season to taste.',mealSoup4:'Put noodles in bowls, pour over hot broth, and finish with scallions and herbs.',mealNoodle1:'Prep and season the beef or pork. Get the noodles and vegetables ready.',mealNoodle2:'Stir-fry the meat quickly over high heat until just cooked, then set aside.',mealNoodle3:'Cook the vegetables, add the noodles with a splash of water or soy sauce, then return the meat.',mealCongee1:'Rinse the rice, add it to a pot with plenty of water or broth, and simmer until the grains open.',mealCongee2:'Add the prepared meat or chicken, stirring gently so it does not stick.',mealCongee3:'Cook until creamy and the meat is done. Season and finish with ginger and scallions.',mealVermicelli1:'Season pork with lemongrass, fish sauce, and a little sugar. Grill or pan-sear until golden and cooked through.',mealVermicelli2:'Cook the vermicelli. Prepare fresh greens and cucumber, and mix a sweet-sour fish sauce.',mealVermicelli3:'Arrange noodles, greens, and pork in bowls. Add the dressing just before serving.',mealFish1:'Simmer tomatoes and pineapple in water until soft. Season with a balanced sweet-sour taste.',mealFish2:'Add fish cake and dill; simmer gently until hot and flavorful.',mealFish3:'Place vermicelli in bowls, ladle over the hot broth, and serve.'});
    const ageOptions=[['<3','under3',.35],['3-5','age35',.5],['6-9','age69',.7],['10-13','age1013',.85],['14+','over13',1]];
    const daysShort={vi:['T2','T3','T4','T5','T6','T7','CN'],en:['Mon','Tue','Wed','Thu','Fri','Sat','Sun']};
    const defaults=()=>({lang:'vi',family:{adults:2,kids:['10-13','3-5','3-5']},plan:[],checked:[],saved:null});
    let state;try{state=Object.assign(defaults(),JSON.parse(localStorage.getItem(KEY)||'{}'));state.family=Object.assign(defaults().family,state.family||{});state.family.kids=Array.isArray(state.family.kids)?state.family.kids:[];state.checked=state.checked||[];state.plan=state.plan||[];}catch{state=defaults()}
    let toastTimer;const tr=(k)=>T[state.lang][k]||T.vi[k]||k;const textOf=(d)=>d[state.lang]||d.vi;const esc=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    function persist(){localStorage.setItem(KEY,JSON.stringify(state))}function toast(k){const el=document.getElementById('toast');el.textContent=tr(k);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200)}
    function ageKey(a){if(ageOptions.some(x=>x[0]===String(a)))return String(a);let n=Number(a);return n<3?'<3':n<=5?'3-5':n<=9?'6-9':n<=13?'10-13':'14+'}function portionUnits(){return state.family.adults+state.family.kids.reduce((s,a)=>s+(ageOptions.find(x=>x[0]===ageKey(a))||ageOptions[3])[2],0)}function scale(){return portionUnits()/2}function fmt(n){return new Intl.NumberFormat(state.lang==='vi'?'vi-VN':'en-US',{maximumFractionDigits:1}).format(n)}
    function seedPlan(){let used={main:[],soup:[],veg:[],meal:[]};return days.map((_,i)=>{const pick=(type,offset)=>{const pool=dishes[type];let idx=(i*3+offset+Math.floor(Math.random()*pool.length))%pool.length;for(let z=0;z<pool.length&&used[type].includes(pool[idx].id);z++)idx=(idx+1)%pool.length;used[type].push(pool[idx].id);return pool[idx].id};if(i===2||i===5)return {style:'onepot',meal:pick('meal',i)};return {style:'rice',main:pick('main',1),soup:pick('soup',4),veg:pick('veg',2)}})}
    function getDish(id){for(const type of Object.keys(dishes)){const d=dishes[type].find(x=>x.id===id);if(d)return {dish:d,type}}return null}
    function validPlan(plan){return Array.isArray(plan)&&plan.length===7&&plan.every(day=>(day.style==='onepot'?[day.meal]:[day.main,day.soup,day.veg]).filter(Boolean).every(id=>!!getDish(id)))}
    if(!validPlan(state.plan))state.plan=seedPlan();if(state.saved&&!validPlan(state.saved.plan))state.saved=null;
    function renderLang(){document.documentElement.lang=state.lang;document.title=tr('pageTitle');document.querySelector('meta[name=description]').content=tr('pageDescription');document.querySelectorAll('[data-t-aria]').forEach(e=>e.setAttribute('aria-label',tr(e.dataset.tAria)));document.querySelectorAll('[data-t]').forEach(e=>{const v=tr(e.dataset.t);if(v)e.innerHTML=v});document.querySelectorAll('[data-html]').forEach(e=>e.innerHTML=tr(e.dataset.html));document.getElementById('langBtn').innerHTML=state.lang==='vi'?'EN / VI':'VI / EN';document.getElementById('servingUnits').textContent=fmt(portionUnits());document.getElementById('familySummary').textContent=state.family.adults+state.family.kids.length;document.getElementById('adultsNum').textContent=state.family.adults;document.getElementById('kidsNum').textContent=state.family.kids.length;document.getElementById('restoreBtn').hidden=!state.saved;renderKids();renderWeekDate();renderPlan();renderMarket()}
    function renderWeekDate(){let d=new Date(),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);let end=new Date(d);end.setDate(end.getDate()+6);const f=new Intl.DateTimeFormat(state.lang==='vi'?'vi-VN':'en-US',{day:'numeric',month:'short'});document.getElementById('weekDate').textContent=`${f.format(d)} — ${f.format(end)}`}
    function renderKids(){const el=document.getElementById('kidAges');el.innerHTML=state.family.kids.map((a,i)=>`<label class="kid-age"><span>🧒 ${tr('children')} ${i+1}</span><select data-age="${i}" aria-label="${tr('children')} ${i+1}">${ageOptions.map(o=>`<option value="${o[0]}" ${ageKey(a)===o[0]?'selected':''}>${tr(o[1])}</option>`).join('')}</select></label>`).join('');el.querySelectorAll('select').forEach(s=>s.addEventListener('change',()=>{state.family.kids[+s.dataset.age]=s.value;persist();renderLang()}))}
    function renderPlan(){const host=document.getElementById('planner');host.innerHTML=days.map((d,i)=>{let today=(new Date().getDay()+6)%7===i,onepot=state.plan[i].style==='onepot'&&state.plan[i].meal,entries=onepot?[['meal',state.plan[i].meal]]:[['main',state.plan[i].main],['soup',state.plan[i].soup],['veg',state.plan[i].veg]];return `<article class="day-card ${today?'today':''}"><div class="day-head"><div class="day-title"><div class="day-stamp">${d[2]}</div><div><h3>${daysShort[state.lang][i]}</h3><small>${today?tr('today')+' · ':''}${tr('dinner')}</small></div></div><span class="day-tag">${onepot?tr('onePot'):`${tr('main')} + ${tr('soup')}`}</span></div><div class="dish-grid ${onepot?'onepot':''}">${entries.map(([type,id])=>dishTile(id,type,i)).join('')}</div></article>`}).join('');host.querySelectorAll('.dish').forEach(tile=>{tile.addEventListener('click',e=>{if(e.target.closest('[data-action=swap]'))return;openRecipe(tile.dataset.id)});tile.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openRecipe(tile.dataset.id)}})});host.querySelectorAll('[data-action="swap"]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();swap(+b.dataset.day,b.dataset.type)}))}
    function dishTile(id,type,day){let found=getDish(id),d=found?.dish;if(!d)return '';return `<div class="dish" role="button" tabindex="0" data-id="${d.id}" aria-label="${esc(textOf(d))} · ${tr('recipeTap')}"><span class="dish-icon">${d.icon}</span><span class="dish-label">${tr(type)}</span><strong class="dish-name">${esc(textOf(d))}</strong><div class="dish-bottom"><span class="dish-time">◷ ${d.time} ${tr('mins')}</span><span class="dish-actions"><button class="icon-btn" title="${tr('swap')}" aria-label="${tr('swap')}" data-action="swap" data-day="${day}" data-type="${type}">⟳</button><span class="recipe-action" aria-hidden="true">↗</span></span></div></div>`}
    function swap(day,type){const pool=dishes[type],used=state.plan.map(p=>p[type]||(type==='meal'?p.meal:null)).filter(Boolean);let options=pool.filter(d=>!used.includes(d.id));if(!options.length)options=pool.filter(d=>d.id!==state.plan[day][type]);state.plan[day][type]=options[Math.floor(Math.random()*options.length)].id;persist();renderPlan();renderMarket()}
    const categories={vi:{meat:'Thịt & trứng',fish:'Cá & hải sản',veg:'Rau củ',pantry:'Gia vị & khác',vegetarian:'Đạm thực vật',seafood:'Cá & hải sản',grains:'Gạo, bún & mì'},en:{meat:'Meat & eggs',fish:'Fish & seafood',veg:'Vegetables',pantry:'Pantry',vegetarian:'Plant protein',seafood:'Fish & seafood',grains:'Rice & noodles'}};
    function niceQty(item){let q=item.q;const u=item.unit;if(u==='g'){q=q<10?Math.ceil(q):q<100?Math.ceil(q/5)*5:Math.ceil(q/50)*50;return q>=1000?`${fmt(q/1000)} kg`:`${fmt(q)} g`}if(u==='ml'){q=q<30?Math.ceil(q/5)*5:q<100?Math.ceil(q/10)*10:Math.ceil(q/25)*25;return q>=1000?`${fmt(q/1000)} L`:`${fmt(q)} ml`}q=Math.max(1,Math.ceil(q));const unitsEn={quả:'pcs',cây:'stalks',bìa:'blocks',lá:'leaves',củ:'pieces',thanh:'sticks',cánh:'whole stars',gói:'packs',nắm:'handfuls',miếng:'pieces'};return `${q} ${state.lang==='en'?(unitsEn[u]||'pcs'):u}`}
    function aggregate(){let map={};state.plan.forEach(day=>Object.values(day).forEach(id=>{const found=getDish(id);if(!found)return;const {dish:d,type}=found;d.ings.forEach(([vi,en,unit,n])=>{if(vi==='nước lọc')return;const key=vi;let category=['thịt heo','thịt ba chỉ','thịt gà','thịt bò','thịt heo xay','trứng gà','sườn heo'].includes(vi)?'meat':['cá phi lê','cá khúc','cá nục','cá lóc','tôm','mực ống','chả cá'].includes(vi)?'fish':['cơm nguội','gạo','bánh phở','bánh tráng','nui','hủ tiếu','bún','miến','mì','bánh canh'].includes(vi)?'grains':'veg';if(['nước mắm','nước tương','tiêu đen','tiêu trắng','nước dừa','nước cốt dừa','đường','giấm gạo','dầu ăn','muối','bột bắp','bột nghệ','dầu mè','dầu hào','rượu nấu ăn','mắm nêm'].includes(vi))category='pantry';let x=map[key]||(map[key]={vi,en,unit,q:0,category});x.q+=Number(n)*scale()})}));return Object.values(map).sort((a,b)=>a.category.localeCompare(b.category)||a.vi.localeCompare(b.vi))}
    function renderMarket(){const items=aggregate(),checked=state.checked;document.getElementById('marketCount').textContent=`${items.length} ${tr('ingredientCount')}`;document.getElementById('tabMarketCount').textContent=items.length?` · ${items.length}`:'';let done=items.filter(x=>checked.includes(x.vi)).length;document.getElementById('progressText').textContent=`${done} / ${items.length} ${tr('bought')}`;document.getElementById('progressFill').style.width=items.length?`${done/items.length*100}%`:'0%';const box=document.getElementById('marketList');if(!items.length){box.innerHTML=`<div class="market-empty">${tr('marketEmpty')}</div>`;return}let groups={};items.forEach(x=>(groups[x.category]||(groups[x.category]=[])).push(x));box.innerHTML=Object.entries(groups).map(([cat,list])=>`<div class="market-group">${categories[state.lang][cat]||categories[state.lang].veg}</div>${list.map(x=>`<label class="market-item ${checked.includes(x.vi)?'checked':''}"><input type="checkbox" data-item="${esc(x.vi)}" ${checked.includes(x.vi)?'checked':''}><span class="market-text">${state.lang==='vi'?esc(x.vi):esc(x.en)}</span><span class="market-qty">${niceQty(x)}</span></label>`).join('')}`).join('');box.querySelectorAll('input').forEach(i=>i.addEventListener('change',()=>{const key=i.dataset.item;if(i.checked&&!state.checked.includes(key))state.checked.push(key);else state.checked=state.checked.filter(x=>x!==key);persist();renderMarket()}))}
    function recipeStepsFor(d,type){let keys;if(type==='main'&&/boiled/.test(d.id))keys=['boiledMeat1','boiledMeat2','boiledMeat3'];else if(type==='main'&&/steamed/.test(d.id))keys=['steam1','steam2','steam3'];else if(type==='main'&&/omelet/.test(d.id))keys=['eggDish1','eggDish2','eggDish3'];else if(type==='main'&&/fish-fried|fish-sauce-chicken|tofu-lemongrass/.test(d.id))keys=['fry1','fry2','fry3'];else if(type==='meal'&&/fried-rice|egg-rice|duong-chau-rice/.test(d.id))keys=['mealRice1','mealRice2','mealRice3','mealFinish'];else if(type==='meal'&&/congee/.test(d.id))keys=['mealCongee1','mealCongee2','mealCongee3','mealFinish'];else if(type==='meal'&&/grilled-pork/.test(d.id))keys=['mealVermicelli1','mealVermicelli2','mealVermicelli3','mealFinish'];else if(type==='meal'&&/beef-noodles|hu-tieu-stirfry/.test(d.id))keys=['mealNoodle1','mealNoodle2','mealNoodle3','mealFinish'];else if(type==='meal'&&/fishcake-noodle/.test(d.id))keys=['mealFish1','mealFish2','mealFish3','mealFinish'];else if(type==='meal')keys=['mealSoup1','mealSoup2','mealSoup3','mealSoup4'];else if(type==='soup')keys=['soup1','soup2','soup3','soup4'];else if(type==='veg'&&(/boil|okra/.test(d.id)))keys=['boil1','boil2','boil3'];else if(type==='veg'&&d.id==='veg-cucumber-tomato')keys=['cucumber1','cucumber2','cucumber3'];else if(type==='veg')keys=['stirVeg1','stirVeg2','stirVeg3','stirVeg4'];else if(d.id==='pork-egg')keys=['porkEgg1','porkEgg2','porkEgg3','stepFinish'];else if(/fish-tomato|sardine-tomato/.test(d.id))keys=['fishTomato1','fishTomato2','fishTomato3','stepFinish'];else if(d.id==='fried-eggplant')keys=['eggplant1','eggplant2','eggplant3','stepFinish'];else if(d.id==='pork-stuffed-tofu')keys=['stuffed1','stuffed2','stuffed3','stepFinish'];else if(d.id==='chicken-curry')keys=['curry1','curry2','curry3','stepFinish'];else if(d.id==='pork-meatballs')keys=['meatball1','meatball2','meatball3','stepFinish'];else if(/tofu/.test(d.id))keys=['tofu1','tofu2','tofu3','stepFinish'];else if(/kho|caramel|braised|pork-pineapple|pork-pickles|shrimp-pork/.test(d.id))keys=['stepPrep','stepFry','stepSimmer','stepFinish'];else keys=['stepPrep','stepFry','stepSimmer','stepFinish'];return keys.map(k=>tr(k))}
    function openRecipe(id){const found=getDish(id);if(!found)return;let d=found.dish;document.getElementById('recipeType').textContent=tr(found.type).toLocaleUpperCase();document.getElementById('recipeTitle').textContent=textOf(d);document.getElementById('recipeMeta').textContent=`◷ ${d.time} ${tr('mins')} · ${tr('forPeople')} ${fmt(portionUnits())}`;document.getElementById('recipeIngredients').innerHTML=d.ings.map(([vi,en,u,n])=>`<div class="ingredient"><span>${state.lang==='vi'?esc(vi):esc(en)}</span><span>${niceQty({q:+n*scale(),unit:u})}</span></div>`).join('');document.getElementById('recipeSteps').innerHTML=(d.steps?.[state.lang]||recipeStepsFor(d,found.type)).map(step=>`<li>${esc(step)}</li>`).join('');document.getElementById('modal').classList.add('open')}
    document.getElementById('closeModal').onclick=()=>document.getElementById('modal').classList.remove('open');
    document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.close).classList.remove('open')));
    document.querySelectorAll('.modal-backdrop').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('open')}));
    document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.modal-backdrop.open').forEach(m=>m.classList.remove('open'))});
    function setView(view){const shopping=view==='shopping';document.getElementById('planner').classList.toggle('hidden-panel',shopping);document.getElementById('marketCard').classList.toggle('hidden-panel',!shopping);document.getElementById('planTab').classList.toggle('active',!shopping);document.getElementById('shopBtn').classList.toggle('active',shopping);if(shopping)renderMarket()}
    document.getElementById('planTab').onclick=()=>setView('plan');document.getElementById('shopBtn').onclick=()=>setView('shopping');document.getElementById('familyOpen').onclick=()=>document.getElementById('familyDialog').classList.add('open');
    document.getElementById('langBtn').onclick=()=>{state.lang=state.lang==='vi'?'en':'vi';persist();renderLang()};document.getElementById('shuffleBtn').onclick=()=>{state.plan=seedPlan();state.checked=[];persist();renderPlan();renderMarket();toast('generated')};document.getElementById('saveBtn').onclick=()=>{state.saved={plan:JSON.parse(JSON.stringify(state.plan)),label:new Intl.DateTimeFormat(state.lang==='vi'?'vi-VN':'en-US',{month:'short',day:'numeric'}).format(new Date())};persist();document.getElementById('restoreBtn').hidden=false;toast('saved')};document.getElementById('restoreBtn').onclick=()=>{if(state.saved){state.plan=JSON.parse(JSON.stringify(state.saved.plan));state.checked=[];persist();renderPlan();renderMarket();toast('restored')}};document.querySelectorAll('[data-count]').forEach(b=>b.addEventListener('click',()=>{let {count,delta}=b.dataset;if(count==='adults')state.family.adults=Math.max(1,Math.min(10,state.family.adults+Number(delta)));else if(delta==='1'&&state.family.kids.length<10)state.family.kids.push('3-5');else if(delta==='-1')state.family.kids.pop();persist();renderLang()}));
    let installPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('appinstalled',()=>{installPrompt=null;toast('installed')});document.getElementById('installBtn').onclick=async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;return}const isiOS=/iphone|ipad|ipod/i.test(navigator.userAgent);document.getElementById('installHelp').innerHTML=`<p>${isiOS?tr('iosInstall'):tr('androidInstall')}</p><ol><li>${state.lang==='vi'?'Mở trang này bằng Safari hoặc Chrome.':'Open this page in Safari or Chrome.'}</li><li>${state.lang==='vi'?'Mở menu Chia sẻ hoặc menu trình duyệt.':'Open the Share menu or browser menu.'}</li><li>${state.lang==='vi'?'Chọn “Thêm vào màn hình chính” hoặc “Cài đặt ứng dụng”.':'Choose “Add to Home Screen” or “Install app”.'}</li></ol>`;document.getElementById('installDialog').classList.add('open')};
    function setNetwork(){const el=document.getElementById('offlineStatus');el.classList.toggle('offline',!navigator.onLine);el.textContent=navigator.onLine?tr('offlineReady'):(state.lang==='vi'?'Đang ngoại tuyến · thực đơn đã lưu trên máy':'Offline · your saved plan is on this device')};window.addEventListener('online',setNetwork);window.addEventListener('offline',setNetwork);if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));
    renderLang();setNetwork();persist();
